package com.shatteredpixel.shatteredpixeldungeon.apd.difficulty;
import com.shatteredpixel.shatteredpixeldungeon.*;
import com.shatteredpixel.shatteredpixeldungeon.actors.*;
import com.shatteredpixel.shatteredpixeldungeon.actors.blobs.Electricity;
import com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero;
import com.shatteredpixel.shatteredpixeldungeon.actors.mobs.Tengu;
import com.shatteredpixel.shatteredpixeldungeon.apd.HeadlessTestSupport;
import com.shatteredpixel.shatteredpixeldungeon.items.potions.brews.ShockingBrew;
import com.shatteredpixel.shatteredpixeldungeon.levels.*;
import com.shatteredpixel.shatteredpixeldungeon.sprites.CharSprite;
import com.watabou.utils.*;
import java.nio.file.*;
import org.junit.*;
import static org.junit.Assert.*;
public class ElectricityDamageProvenanceTest {
 static final int CELL=112, WATER=113;
 static class Probe extends Electricity {int[] pending(){return off;}}
 static class Quiet extends CharSprite{@Override public void showStatus(int c,String s,Object...a){} @Override public void showStatusWithIcon(int c,String s,int i,Object...a){}}
 static class Target extends Char {Object source;int calls;Target(int cell){HP=HT=1000;pos=cell;sprite=new Quiet();}@Override public void damage(int d,Object s){source=s;calls++;super.damage(d,s);}}
 Hero hero;Level level;int depth;Bundle run;java.util.Set<Actor> actors;
 @Before public void setup()throws Exception{HeadlessTestSupport.start();hero=Dungeon.hero;level=Dungeon.level;depth=Dungeon.depth;run=new Bundle();Dungeon.apdStoreCustomRules(run);actors=Actor.all();Dungeon.hero=new Hero();Dungeon.depth=14;Dungeon.level=new SewerLevel();java.lang.reflect.Method size=Level.class.getDeclaredMethod("setSize",int.class,int.class);size.setAccessible(true);size.invoke(Dungeon.level,15,15);java.util.Arrays.fill(Dungeon.level.map,Terrain.EMPTY);java.util.Arrays.fill(Dungeon.level.passable,true);Dungeon.level.blobs=new java.util.HashMap<>();Dungeon.level.heaps=new SparseArray<>();}
 @After public void cleanup(){for(Actor a:Actor.all())if(!actors.contains(a))Actor.remove(a);Dungeon.hero=hero;Dungeon.level=level;Dungeon.depth=depth;Dungeon.apdRestoreCustomRules(run);assertEquals(OffensiveDamageOrigin.UNATTRIBUTED,OffensiveEffectContext.current());}
 void rules(int p,int e,int b){Bundle saved=new Bundle(),r=new Bundle();CustomDungeonRules.defaults().with(CustomDungeonRules.Slider.PLAYER_DAMAGE,p).with(CustomDungeonRules.Slider.ENEMY_DAMAGE,e).with(CustomDungeonRules.Slider.BOSS_DAMAGE,b).store(r);saved.put("apd_custom_rules",r);Dungeon.apdRestoreCustomRules(saved);}
 void seed(Electricity blob,int cell,int amount,OffensiveDamageOrigin role){try(OffensiveEffectContext ignored=OffensiveEffectContext.enter(role)){blob.seed(Dungeon.level,cell,amount);}}
 int raw(long seed){Random.pushGenerator(seed);try{return Math.round(Random.Float(2+Dungeon.scalingDepth()/5f));}finally{Random.popGenerator();}}
 @Test public void actualTicksUseEachDamageSliderExactlyOnce(){for(OffensiveDamageOrigin role:new OffensiveDamageOrigin[]{OffensiveDamageOrigin.PLAYER,OffensiveDamageOrigin.ENEMY,OffensiveDamageOrigin.BOSS})for(int pct=25;pct<=500;pct+=25){rules(role==OffensiveDamageOrigin.PLAYER?pct:100,role==OffensiveDamageOrigin.ENEMY?pct:100,role==OffensiveDamageOrigin.BOSS?pct:100);Probe blob=new Probe();seed(blob,CELL,5,role);Target t=new Target(CELL);Actor.add(t);int value=raw(41027);Random.pushGenerator(41027);try{blob.act();}finally{Random.popGenerator();}assertEquals(1000-Math.round(value*pct/100f),t.HP);assertSame(blob,t.source);assertEquals(1,t.calls);Actor.remove(t);}}
 @Test public void mixedAndEnvironmentalFieldsKeepOneOriginalDamageEvent(){rules(200,300,500);Probe mixed=new Probe();seed(mixed,CELL,5,OffensiveDamageOrigin.PLAYER);seed(mixed,CELL,4,OffensiveDamageOrigin.BOSS);Target t=new Target(CELL);Actor.add(t);int value=raw(8119);Random.pushGenerator(8119);try{mixed.act();}finally{Random.popGenerator();}assertEquals(1000-Math.round(value*(5*200+4*500)/(9f*100f)),t.HP);assertEquals(1,t.calls);Actor.remove(t);Probe environmental=new Probe();seed(environmental,CELL,5,OffensiveDamageOrigin.UNATTRIBUTED);Target u=new Target(CELL);Actor.add(u);Random.pushGenerator(8119);try{environmental.act();}finally{Random.popGenerator();}assertEquals(1000-value,u.HP);Actor.remove(u);}
 @Test public void waterSpreadAndSaveReloadRetainCreatorWhileLegacyStaysUnknown(){rules(200,300,500);Dungeon.level.water[WATER]=true;Probe original=new Probe();seed(original,CELL,5,OffensiveDamageOrigin.ENEMY);Bundle saved=new Bundle();original.storeInBundle(saved);Probe restored=new Probe();restored.restoreFromBundle(saved);Target t=new Target(WATER);Actor.add(t);int value=raw(8821);Random.pushGenerator(8821);try{restored.act();}finally{Random.popGenerator();}assertEquals(1000-Math.round(value*3f),t.HP);Actor.remove(t);CellDamageOrigins.clearMetadata(saved,"apd_electric_origins");Probe legacy=new Probe();legacy.restoreFromBundle(saved);Target u=new Target(WATER);Actor.add(u);Random.pushGenerator(8821);try{legacy.act();}finally{Random.popGenerator();}assertEquals(1000-value,u.HP);Actor.remove(u);}
 @Test public void clearReuseAndMalformedMetadataCannotStealOrRewriteOwnership(){rules(200,300,500);Probe blob=new Probe();seed(blob,CELL,5,OffensiveDamageOrigin.BOSS);blob.clear(CELL);seed(blob,CELL,5,OffensiveDamageOrigin.UNATTRIBUTED);Target t=new Target(CELL);Actor.add(t);int value=raw(725);Random.pushGenerator(725);try{blob.act();}finally{Random.popGenerator();}assertEquals(1000-value,t.HP);Actor.remove(t);Probe bad=new Probe();seed(bad,CELL,5,OffensiveDamageOrigin.BOSS);Bundle saved=new Bundle();bad.storeInBundle(saved);int[] density=saved.getIntArray("cur");saved.put("apd_electric_origins_mass",new String[]{"0","0","0","NaN"});try{new Probe().restoreFromBundle(saved);fail();}catch(IllegalArgumentException expected){}assertArrayEquals(density,saved.getIntArray("cur"));assertEquals("NaN",saved.getStringArray("apd_electric_origins_mass")[3]);}
 @Test public void neutralTrackingPreservesWaterTopologyTurnsDamageAndRng(){rules(100,100,100);Dungeon.level.water[WATER]=true;Probe tagged=new Probe();seed(tagged,CELL,5,OffensiveDamageOrigin.PLAYER);Target a=new Target(WATER);Actor.add(a);long next;Random.pushGenerator(1907);try{tagged.act();next=Random.Long();}finally{Random.popGenerator();}Actor.remove(a);Probe plain=new Probe();seed(plain,CELL,5,OffensiveDamageOrigin.UNATTRIBUTED);Target b=new Target(WATER);Actor.add(b);Random.pushGenerator(1907);try{plain.act();assertEquals(next,Random.Long());}finally{Random.popGenerator();}assertEquals(a.HP,b.HP);assertArrayEquals(plain.cur,tagged.cur);assertArrayEquals(plain.pending(),tagged.pending());assertEquals(plain.volume,tagged.volume);assertEquals(plain.cooldown(),tagged.cooldown(),0);Actor.remove(b);}
 @Test public void actualShockingBrewUsesPlayerDamageWithoutChangingItsField(){rules(200,500,500);Target t=new Target(CELL);Actor.add(t);new ShockingBrew().shatter(CELL);Electricity field=(Electricity)Dungeon.level.blobs.get(Electricity.class);assertNotNull(field);field.act();int value=raw(3319);Random.pushGenerator(3319);try{field.act();}finally{Random.popGenerator();}assertEquals(1000-Math.round(value*2f),t.HP);assertSame(field,t.source);Actor.remove(t);}
 @Test public void actualTenguAndPylonFieldsUseBossRatherThanEnemyDamage(){rules(100,500,200);Target t=new Target(CELL);Actor.add(t);Tengu.ShockerAbility.ShockerBlob shock=new Tengu.ShockerAbility.ShockerBlob();shock.seed(Dungeon.level,CELL,1);shock.act();assertEquals(1000-2*(2+Dungeon.scalingDepth()),t.HP);assertEquals(Electricity.class,t.source.getClass());Actor.remove(t);Target u=new Target(CELL);Actor.add(u);CavesBossLevel.PylonEnergy energy=new CavesBossLevel.PylonEnergy();energy.seed(Dungeon.level,CELL,1);int value;Random.pushGenerator(5531);try{value=Random.NormalIntRange(6,12);}finally{Random.popGenerator();}Random.pushGenerator(5531);try{energy.act();}finally{Random.popGenerator();}assertEquals(1000-Math.round(value*2f),u.HP);assertEquals(Electricity.class,u.source.getClass());Actor.remove(u);}
 @Test public void everyKnownPlayerElectricFieldUsesTheAttributedEntryPoint()throws Exception{Path root=Paths.get(System.getProperty("apd.game.src"));for(String path:new String[]{"items/potions/brews/ShockingBrew.java","actors/hero/abilities/mage/ElementalBlast.java","actors/hero/abilities/duelist/ElementalStrike.java"}){String text=Files.readString(root.resolve(path));assertTrue(path,text.contains("Electricity.seedAttributed("));assertFalse(path,text.contains("Blob.seed( cell, 4, Electricity.class )"));assertFalse(path,text.contains("Blob.seed(cell, Math.round(8 * powerMulti), Electricity.class)"));}}
}
